"""Explicit Spark schemas for the Silver datasets."""
from pyspark.sql.types import (ArrayType, BooleanType, DoubleType, IntegerType, LongType, MapType,
    StringType, StructField, StructType, TimestampType)

EVIDENCE = [StructField("source_artifact_path", StringType()), StructField("artifact_type", StringType()),
            StructField("parser_name", StringType()), StructField("parser_version", StringType()),
            StructField("source_line_start", IntegerType()), StructField("source_line_end", IntegerType()),
            StructField("extraction_timestamp", TimestampType())]
def schema(fields): return StructType(fields)
RUNS = schema([StructField("run_id", StringType(), False), StructField("design_id", StringType()), StructField("design_name", StringType()), StructField("flow", StringType()), StructField("flow_version", StringType()), StructField("technology", StringType()), StructField("process_node_nm", IntegerType()), StructField("timestamp", TimestampType()), StructField("flow_status", StringType()), StructField("timing_status", StringType()), StructField("routing_status", StringType()), StructField("drc_status", StringType()), StructField("antenna_status", StringType()), StructField("lvs_status", StringType()), StructField("overall_status", StringType())])
RUN_CONFIGURATIONS = schema([StructField("run_id", StringType(), False), StructField("configuration", MapType(StringType(), StringType())), *EVIDENCE])
RUN_ARTIFACTS = schema([StructField("run_id", StringType(), False), StructField("source_artifact_path", StringType()), StructField("artifact_type", StringType()), StructField("format", StringType()), StructField("stage", StringType()), StructField("exists", BooleanType()), StructField("parse_success", BooleanType()), StructField("parse_errors", ArrayType(StringType())), StructField("parser_name", StringType()), StructField("parser_version", StringType()), StructField("extraction_timestamp", TimestampType())])
METRIC_OBSERVATIONS = schema([StructField("run_id", StringType(), False), StructField("metric_name", StringType()), StructField("metric_value", DoubleType()), StructField("metric_scope", StringType()), StructField("unit", StringType()), *EVIDENCE])
TIMING_PATHS = schema([StructField("run_id", StringType(), False), StructField("path_kind", StringType()), StructField("path_id", StringType()), StructField("startpoint", StringType()), StructField("endpoint", StringType()), StructField("path_group", StringType()), StructField("start_clock", StringType()), StructField("end_clock", StringType()), StructField("required_time", DoubleType()), StructField("arrival_time", DoubleType()), StructField("slack", DoubleType()), StructField("data_path_delay", DoubleType()), StructField("logic_depth", IntegerType()), StructField("fanout", IntegerType()), StructField("clock_skew", DoubleType()), *EVIDENCE])
CELL_STATISTICS = schema([StructField("run_id", StringType(), False), StructField("cell_type", StringType()), StructField("cell_count", LongType()), *EVIDENCE])
VIOLATIONS = schema([StructField("run_id", StringType(), False), StructField("violation_type", StringType()), StructField("layer", StringType()), StructField("location", StringType()), StructField("description", StringType()), StructField("violating_net", StringType()), StructField("ratio", DoubleType()), StructField("limit", DoubleType()), *EVIDENCE])
VALIDATION_RESULTS = schema([StructField("check_id", StringType()), StructField("run_id", StringType()), StructField("check_name", StringType()), StructField("check_category", StringType()), StructField("expected_value", StringType()), StructField("actual_value", StringType()), StructField("difference", DoubleType()), StructField("tolerance", DoubleType()), StructField("check_status", StringType()), StructField("explanation", StringType())])
RUN_QUALITY = schema([StructField("run_id", StringType(), False), StructField("artifact_completeness_score", DoubleType()), StructField("parsing_success_score", DoubleType()), StructField("schema_validity_score", DoubleType()), StructField("cross_report_consistency_score", DoubleType()), StructField("overall_data_quality_score", DoubleType()), StructField("quality_status", StringType()), StructField("failed_checks", LongType()), StructField("warning_checks", LongType())])
AUDIT_SCHEMA = schema([StructField("run_id", StringType(), False), StructField("source_artifact_path", StringType()), StructField("artifact_type", StringType()), StructField("format", StringType()), StructField("stage", StringType()), StructField("exists", BooleanType()), StructField("parse_success", BooleanType()), StructField("parse_errors", ArrayType(StringType(), containsNull=False)), StructField("parser_name", StringType()), StructField("parser_version", StringType()), StructField("extraction_timestamp", TimestampType())])
SCHEMAS = {"runs": RUNS, "run_configurations": RUN_CONFIGURATIONS, "run_artifacts": RUN_ARTIFACTS, "metric_observations": METRIC_OBSERVATIONS, "timing_paths": TIMING_PATHS, "cell_statistics": CELL_STATISTICS, "violations": VIOLATIONS, "validation_results": VALIDATION_RESULTS, "run_quality": RUN_QUALITY}
